// Data Structures & Algorithms roadmap questions (120): 15 levels × 8, easiest →
// hardest. Authored as a single 8-per-level list and built directly (like the
// other 15-level topics). See lib/roadmap.ts for the level titles.

import type { Seed } from './roadmap-build';

export const dsaSeeds: Seed[] = [
  // ── Level 1 — Complexity Basics ────────────────────────────────────────
  { q: 'An algorithm takes roughly four times as many operations when the input size doubles. What is time complexity describing here?', opts: ['How much stored memory the implementation allocates', 'How running work grows as the input size grows', 'How many source lines express the algorithm', 'How much wall-clock time one specific computer used once'], a: 1, e: 'Time complexity describes how the amount of work grows as a function of input size n, and four times the work per doubling is the signature of n-squared growth. Memory growth is space complexity, and one stopwatch reading on one machine measures constant factors and hardware rather than growth.', intro: 'The stem gives a ratio: double the input, four times the work. Ask what quantity such a ratio is a statement about.', tags: ['DSA', 'Complexity'] },
  { q: 'What does "space complexity" measure?', opts: ['How long an algorithm runs as the input grows', 'How much extra memory an algorithm uses as input grows', 'How much memory the machine running it has available', 'How many variables the source code declares'], a: 1, e: 'Space complexity is a growth function like time complexity, but for memory the algorithm itself needs: an in-place sort that reuses the input array is O(1) extra space, while one that copies the array first is O(n). Runtime growth is time complexity, and the size of the source or the machine\'s installed RAM does not change with n at all.', intro: 'Ask which resource is being counted, and whether the count changes when n grows.', tags: ['DSA', 'Complexity'] },
  { q: 'When analyzing complexity, what does the variable n usually represent?', opts: ['The number of CPU cores available', 'The size of the input, such as an array\'s element count', 'The number of times the function is called', 'The recursion depth the language allows'], a: 1, e: 'By convention n is the size of the input - array length, string length, node count - because complexity states how work grows with that quantity. Core count is a property of the machine, and a recursion limit is a property of the language; both are fixed for a run, so neither is what the growth function is measured against.', intro: 'Complexity is always stated relative to something that can grow. Ask what that something is.', tags: ['DSA', 'Complexity'] },
  { q: 'A feature looks values up by key thousands of times per request and never needs them in order. Why does the choice of data structure matter here?', opts: ['Each structure makes a different set of operations cheap, and lookup by key is cheap only in some of them', 'Every structure supports the same operations, so only total memory changes', 'The structure affects how the code reads, but the operation costs are the same', 'The structure fixes the order values come back in, which this feature depends on'], a: 0, e: 'Picking a structure is picking which operations are cheap: a hash map answers lookup by key in average O(1), while an unsorted array has to scan and costs O(n). The idea that structures differ only in memory or in readability is the misconception here - the cost of the operation you perform most is what actually changes, and this feature explicitly does not need ordering.', intro: 'The feature names one operation it performs constantly. Ask what differs between structures for that one operation.', tags: ['DSA', 'Complexity'] },
  { q: 'Why do we usually analyze the "worst case" of an algorithm?', opts: ['It gives an upper bound that holds for every input of that size', 'It reports the time most inputs will actually take', 'It describes what happens once constant factors are measured', 'It is the only case Big-O notation can describe'], a: 0, e: 'Worst-case analysis bounds the running time for every input of size n, so it is something you can size a timeout or an SLO against. The average case answers a different question - what typical inputs cost - and Big-O is only notation for bounding a growth function, so it can be applied to the best, average, or worst case alike.', intro: 'Ask what you would need to tell a caller who asks how slow this can get.', tags: ['DSA', 'Complexity'] },
  { q: 'If algorithm A does fewer operations than algorithm B for every input size, A is generally:', opts: ['Less efficient', 'More efficient', 'Identical to B', 'Impossible to compare'], a: 1, e: 'Doing fewer operations for the same work means A is more efficient than B.', tags: ['DSA', 'Complexity'] },
  { q: 'One loop always checks the first 5 elements of an array; another visits every element. As n grows, how do the two amounts of work compare?', opts: ['The second loop\'s work grows with n while the first stays at 5 steps', 'Both grow with n, the second one twice as fast', 'The first grows with n because it repeats 5 checks', 'Neither grows; both do a fixed amount of work'], a: 0, e: 'Work proportional to n rises without bound as n grows, while a fixed 5 checks does not, no matter how large the array gets. That is the difference between O(n) and O(1), and it holds even though 5 is larger than 1 - Big-O compares how the cost moves with n, not the cost at one particular n.', intro: 'Count the checks each loop performs when n is 10, then again when n is 1000.', tags: ['DSA', 'Complexity'] },
  { q: 'An algorithm whose running time does not change as the input grows is said to run in:', opts: ['Constant time', 'Linear time', 'Quadratic time', 'Exponential time'], a: 0, e: 'Constant time, written O(1), means the number of steps is bounded by a fixed amount however large n is - reading a[i] is the standard example, since it costs the same at n = 10 and at n = 10 million. Linear time would rise in step with n, and quadratic and exponential rise faster still; all three change when the input changes, which the stem rules out.', intro: 'Compare the step count at n = 10 with the step count at n = 10 million before naming the class.', tags: ['DSA', 'Complexity'] },

  // ── Level 2 — Big-O Notation ───────────────────────────────────────────
  { q: 'What does Big-O notation express?', opts: ['The exact number of seconds an algorithm takes', 'An upper bound on how the work grows with input size', 'The exact operation count including constant factors', 'The amount of memory an algorithm allocates'], a: 1, e: 'Big-O bounds a growth function from above while ignoring constant factors and lower-order terms, so O(n) says the work rises at most in proportion to n. Seconds and exact operation counts are exactly what it discards - they depend on the machine and the constants - and memory growth is described by space complexity instead.', intro: 'Big-O deliberately discards the parts that depend on the machine. Ask what survives that.', tags: ['DSA', 'Big-O'] },
  { q: 'Reading a[i] from an array takes the same number of steps whether the array holds 10 items or 10 million. Which Big-O states that?', opts: ['O(1)', 'O(log n)', 'O(n)', 'O(n squared)'], a: 0, e: 'O(1) is constant time: the work is bounded by a fixed amount however large n is, which is what indexed access into a contiguous array gives. O(log n) still grows with n, slowly, and O(n) and O(n squared) grow with it directly, so none of the three can describe a cost that is flat in n.', intro: 'Work out what each notation predicts as n goes from 10 to 10 million, then compare that with the stem.', tags: ['DSA', 'Big-O'] },
  { q: 'Which Big-O describes linear time?', opts: ['O(1)', 'O(log n)', 'O(n)', 'O(n²)'], a: 2, e: 'O(n) means the running time grows in direct proportion to the input size n.', tags: ['DSA', 'Big-O'] },
  { q: 'In Big-O, what is O(2n + 5) simplified to?', opts: ['O(2n)', 'O(5)', 'O(2n + 5)', 'O(n)'], a: 3, e: 'Big-O drops constant factors and lower-order terms, so 2n + 5 and n describe the same growth: doubling n roughly doubles both. Counting a 2n + 5 loop gives 25, 205 and 2005 operations at n = 10, 100, 1000, so operations per element settle at a constant. O(2n) and O(2n + 5) are not wrong arithmetic, they are simply unsimplified, while O(5) would claim the work never grows at all.', intro: 'Ask which part of 2n + 5 still matters when n is a million.', tags: ['DSA', 'Big-O'] },
  { q: 'For n = 1,000,000, which of these growth rates means the most work?', opts: ['O(log n)', 'O(n)', 'O(n log n)', 'O(n²)'], a: 3, e: 'At n = 1,000,000 the four come to roughly 20, 1e6, 2e7 and 1e12 steps, so n² is about fifty thousand times more work than n log n and a million times more than n. The order O(log n) < O(n) < O(n log n) < O(n²) holds for every large n, which is why an accidental nested loop over a big collection is the classic performance bug.', intro: 'Substitute the million for n and compare four numbers rather than four shapes.', tags: ['DSA', 'Big-O'] },
  { q: 'Order these from slowest to fastest growth: O(n), O(1), O(n²), O(log n).', opts: ['O(n²), O(n), O(log n), O(1)', 'O(1), O(log n), O(n), O(n²)', 'O(1), O(n), O(log n), O(n²)', 'O(log n), O(1), O(n), O(n²)'], a: 1, e: 'Slowest-growing to fastest is O(1) < O(log n) < O(n) < O(n²): at n = 1,000,000 that is about 1, 20, 1e6 and 1e12 steps. The two near-miss orderings each swap one pair - putting O(n) ahead of O(log n) fails for every n above 2, and putting O(log n) ahead of O(1) fails for every n of 2 or more, since a constant never grows at all.', intro: 'Pick one large n, work out all four values, and read the order off the numbers.', tags: ['DSA', 'Big-O'] },
  { q: 'A loop that runs n times, nested inside another loop that runs n times, is typically:', opts: ['O(n)', 'O(log n)', 'O(n²)', 'O(1)'], a: 2, e: 'The inner loop runs n times for each of the outer loop\'s n passes, so the body executes n × n times: counting for n = 8, 16, 32 gives 64, 256 and 1024, a fourfold rise each time n doubles. That is O(n²). O(n) would only double per doubling, and neither O(log n) nor O(1) grows anywhere near that rate.', intro: 'Count how many times the inner body runs during a single pass of the outer loop, then multiply.', tags: ['DSA', 'Big-O'] },
  { q: 'When we add two sequential steps that are O(n) and O(n²), the overall complexity in simplest Big-O form is:', opts: ['O(n)', 'O(n³)', 'O(n²)', 'O(2n²)'], a: 2, e: 'Running one step after another adds their costs, and n + n² is dominated by n²: counting operations at n = 10, 100, 1000 gives 110, 10100 and 1001000, which is n² plus a shrinking remainder. O(n³) would require nesting the second step inside the first rather than running them in sequence, and O(2n²) would need both steps to be quadratic - and even then Big-O drops the 2.', intro: 'Sequential steps add rather than multiply. Add them, then keep the term that wins for large n.', tags: ['DSA', 'Big-O'] },

  // ── Level 3 — Arrays ───────────────────────────────────────────────────
  { q: 'What is the time complexity of accessing an array element by its index?', opts: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], a: 0, e: 'For an array held in one contiguous block, a[i] is a single address computation - base + i × element size - so the cost does not depend on the length. This is access by index only: finding a value whose index you do not know still costs O(n). JavaScript gives you this while the engine keeps the array packed; assigning far past the end makes V8 switch the array to a dictionary representation, which is one reason to avoid holes.', intro: 'Index access computes an address instead of looking for anything. Ask whether that computation depends on how many elements exist.', tags: ['DSA', 'Arrays'] },
  { q: 'An array `a` holds 5 elements. Which expression reads the last one?', opts: ['a[5]', 'a[a.length]', 'a[a.length - 1]', 'a[-1]'], a: 2, e: 'With zero-based indexing a 5-element array has valid indexes 0 through 4, so the last element is a[a.length - 1], here a[4]. Both a[5] and a[a.length] read one past the end and evaluate to undefined rather than throwing, and a[-1] is only a property named "-1" that was never set - JavaScript has no negative indexing, though a.at(-1) does count back from the end.', intro: 'List the valid indexes for five elements, then check what each expression actually evaluates to.', tags: ['DSA', 'Arrays'] },
  { q: 'What does this print?\n\n```js\nconst a = [10, 20, 30];\nconsole.log(a[3], a.at(-1));\n```', opts: ['undefined 30', '30 30', 'undefined undefined', 'It throws a RangeError'], a: 0, e: 'Valid indexes are 0 to 2, so a[3] is a property that was never set and evaluates to undefined - JavaScript does not range-check array reads, so nothing throws. a.at(-1) counts back from the end and returns 30. Reading past the end silently is why an off-by-one usually surfaces later, as an error about undefined, rather than at the read itself.', intro: 'Check how many slots the array has, then what `at` does with a negative argument.', tags: ['DSA', 'Arrays'] },
  { q: 'Searching for a value in an unsorted array (linear search) is, in the worst case:', opts: ['O(1)', 'O(log n)', 'O(n)', 'O(n²)'], a: 2, e: 'With no ordering to exploit, the only way to be certain a value is absent is to inspect every element: searching an 8-element array for a missing value took 8 comparisons, while a value sitting first took 1. The worst case is therefore O(n), and the best case is O(1). O(log n) is out of reach because halving the search space requires sorted data.', intro: 'Ask how many elements you can be forced to look at before you are allowed to give up.', tags: ['DSA', 'Arrays'] },
  { q: 'Why is inserting an element at the beginning of an array O(n)?', opts: ['Arrays must be re-sorted after every insertion', 'Every element after the insertion point moves one slot to the right', 'Inserting always allocates a brand-new backing buffer', 'The array\'s length has to be recomputed by counting elements'], a: 1, e: 'Contiguous storage puts index i at a fixed offset, so making room at the front moves all n existing elements one slot right: unshift on a 40-element array touched all 40 indexes, while push touched one. Reallocation can also happen when the buffer is full, but it is not the reason the cost is linear - the shifting happens even when there is spare capacity.', intro: 'The new element needs slot 0, which is already occupied. Ask what has to happen to everything after it.', tags: ['DSA', 'Arrays'] },
  { q: 'What does this print?\n\n```js\nconst a = [1, 2, 3];\na.push(4);\na.unshift(0);\nconsole.log(a);\n```', opts: ['[0, 1, 2, 3, 4]', '[1, 2, 3, 4, 0]', '[0, 4, 1, 2, 3]', '[1, 2, 3, 0, 4]'], a: 0, e: 'push appends 4 to the end and unshift inserts 0 at the front, giving [0, 1, 2, 3, 4]. The two are not symmetric in cost: push writes one slot, while unshift moves every existing element one position right - 40 index writes on a 40-element array against push\'s one - so building a list by repeated unshift is O(n²) overall.', intro: 'Apply the two calls in order, and be sure which end each method touches.', tags: ['DSA', 'Arrays'] },
  { q: 'Compared with linked lists, what is a key property of arrays?', opts: ['They store elements in one contiguous block of memory', 'They store a next-pointer alongside every element', 'They can grow in place without ever copying elements', 'They keep elements sorted as they are inserted'], a: 0, e: 'Contiguity is what buys O(1) index access: the address is base + i × element size, with no traversal. A linked list instead stores a pointer per node, which is what lets it splice in the middle without shifting but costs O(n) to reach position k. In JavaScript this is an engine choice rather than a guarantee - V8 keeps a dense array packed but moves a sparse one to a dictionary representation, and delete on an element leaves a hole while length stays the same.', intro: 'One structure computes where element i lives; the other has to follow links to reach it.', tags: ['DSA', 'Arrays'] },
  { q: 'What does removing the last element of an array (pop) typically cost?', opts: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], a: 0, e: 'Removing the last element clears one slot and decrements the length, so the cost is independent of n: pop touched exactly one index on arrays of 10, 20 and 40 elements. shift is the mirror image - it removes the first element and must move the other n-1 left, which measured 40 index reads and 39 writes at n = 40. That difference is why an array used as a queue is O(n) per dequeue while an array used as a stack is not.', intro: 'Nothing sits after the last element, so nothing has to move. Compare that with removing the first element.', tags: ['DSA', 'Arrays'] },

  // ── Level 4 — Strings ──────────────────────────────────────────────────
  { q: 'An algorithm scans text from left to right and compares each position with the next. Which abstract model is most useful?', opts: ['An ordered sequence of text units', 'One numeric value for the whole string', 'An unordered map with no positions', 'A binary tree chosen by character value'], a: 0, e: 'A left-to-right scan needs positions and an order between them, which is exactly what an ordered sequence provides; an unordered map has no positions and a single number has no parts. The unit of that sequence is a separate decision - bytes, UTF-16 code units, code points, or grapheme clusters - and choosing it wrongly is what breaks text handling for emoji and combining marks.', intro: 'Ask which operations the scan actually performs, then keep the smallest model that supports them.', tags: ['DSA', 'Strings'] },
  { q: 'What does this print?\n\n```js\nconsole.log("hello".length, "😀".length);\n```', opts: ['5 2', '5 1', '6 2', '5 0'], a: 0, e: 'String.prototype.length is the number of UTF-16 code units. "hello" needs five of them, so there length happens to equal the character count, but an emoji outside the Basic Multilingual Plane is stored as a surrogate pair and reports 2 - while [..."😀"].length is 1, because iteration walks code points. This is why length is the wrong measure for a character limit on user-entered text.', intro: 'length counts storage units, not what a reader would call characters.', tags: ['DSA', 'Strings'] },
  { q: 'What are the two logged values?\n\n```js\nconst s = "cat";\nconsole.log(s.charAt(3), s[3]);\n```', opts: ['"" and undefined', 'undefined and undefined', '"" and ""', 'It throws a RangeError'], a: 0, e: 'charAt clamps an out-of-range index to the empty string, while bracket access is an ordinary property read and yields undefined. Neither throws - JavaScript does not range-check string indexing - so an off-by-one shows up as a strange value rather than an error. The difference matters when you test the result: s[i] === "" is never true, while s.charAt(i) === "" is exactly how you detect the end.', intro: 'Index 3 is past the end of a three-character string. Look up what each of the two reads returns there.', tags: ['DSA', 'Strings'] },
  { q: 'In many languages, strings are immutable. This means:', opts: ['Their characters cannot be changed in place', 'The variable holding one cannot be reassigned', 'Two equal strings are always the same object', 'Concatenation modifies the left-hand string'], a: 0, e: 'The characters of an existing string can never change: s[0] = "z" is silently ignored in sloppy mode and throws a TypeError under "use strict", and replace returns a new string while the original is untouched. Reassigning a variable is a different thing - let s = "a"; s = "b" is fine - and concatenation likewise builds a new string rather than extending the left operand, which is why repeated concatenation in a loop can be costly.', intro: 'Ask what happens to the original string when a method like replace appears to change it.', tags: ['DSA', 'Strings'] },
  { q: 'Which approach checks whether a normalized string is a palindrome in O(n) time and O(1) extra space?', opts: ['Sort the characters and compare adjacent values', 'Compare characters from both ends while moving two indexes inward', 'Insert every character into a set and check its size', 'Generate every permutation and look for the reverse'], a: 1, e: 'A palindrome reads the same in both directions, so comparing mirrored positions with two indexes settles it in at most n/2 comparisons and keeps only those two indexes - O(n) time, O(1) extra space. Sorting the characters destroys the positions the property is about, a set of characters costs O(n) extra space and answers a different question, and generating permutations is factorial work for a linear problem.', intro: 'Work out the time and the extra space each approach needs before comparing them with the two budgets.', tags: ['DSA', 'Strings'] },
  { q: 'What does the method chain return?\n\n```js\n["ab", "cd"].join("").split("").reverse().join("");\n```', opts: ['"dcba"', '"cdab"', '["d", "c", "b", "a"]', '"abcd"'], a: 0, e: 'join("") turns ["ab","cd"] into "abcd", split("") gives ["a","b","c","d"], reverse mutates that array to ["d","c","b","a"], and the final join("") makes "dcba" - the array-valued option is what you would get if the last join were missing. The idiom is not safe for arbitrary text: split("") cuts on UTF-16 code units, so reversing "ab😀" produces a broken surrogate pair, where [...s].reverse().join("") keeps the emoji intact.', intro: 'Note the type after each call: one of these steps hands you an array rather than a string.', tags: ['DSA', 'Strings'] },
  { q: 'Comparing two strings of length n character-by-character is, in the worst case:', opts: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], a: 1, e: 'Equality has to inspect every position before it can answer yes, so two equal strings of length n cost n comparisons - measured as 10 for two identical 10-character strings, against 1 when they differ at the first character. The worst case is therefore O(n) and the best case O(1); a length check or a cached hash can rule out inequality sooner but cannot confirm equality. That early exit is also why comparing secrets with === leaks timing information.', intro: 'Ask when you are allowed to stop comparing, and when you are not.', tags: ['DSA', 'Strings'] },
  { q: 'Which test correctly decides whether two normalized strings are anagrams?', opts: ['Check whether one string equals the reverse of the other', 'Check whether both strings contain the same set of distinct letters', 'Check whether their first and last letters match', 'Compare their character-frequency maps'], a: 3, e: 'Anagrams use every character the same number of times, so comparing frequency maps is exactly the test - and counting is what the other answers drop. A set of distinct letters calls "aab" and "abb" anagrams because both contain only a and b, reversal is a much stronger and unrelated condition, and first-and-last letters are satisfied by countless non-anagrams.', intro: 'Try each test on \'listen\' and \'silent\', then on \'aab\' and \'abb\'.', tags: ['DSA', 'Strings'] },

  // ── Level 5 — Hash Tables ──────────────────────────────────────────────
  { q: 'What is the average-case time to look up a value by key in a hash table?', opts: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], a: 0, e: 'Hashing the key produces a bucket index, so the lookup goes to one bucket instead of scanning: with 100 keys spread over 64 buckets the deepest bucket held 5 entries, a small constant rather than a function of n. This is the average case, and it assumes a hash that distributes keys and a load factor kept bounded by resizing - with every key in one bucket the same lookup walks all n entries and becomes O(n).', intro: 'The key is turned into a bucket index directly. Ask what has to be true for that bucket to hold only a few entries.', tags: ['DSA', 'Hash Tables'] },
  { q: 'What is the role of a hash function in a hash table?', opts: ['To sort the keys', 'To encrypt the data', 'To map a key to an index/bucket', 'To count the elements'], a: 2, e: 'A hash function turns a key of any type into an integer, which is reduced to a bucket index so the lookup can go straight to one bucket. It is not encryption: it is deliberately one-way and lossy, with no key that reverses it and no confidentiality guarantee. It also imposes no order - two keys whose hashes are adjacent have no relationship - which is why a hash table cannot answer range queries.', intro: 'Follow one insert: you have a key and an array of buckets. Ask what has to happen between the two.', tags: ['DSA', 'Hash Tables'] },
  { q: 'A "collision" in a hash table occurs when:', opts: ['Two different keys hash to the same bucket', 'Two entries are stored with the same value', 'A key is looked up before it has been inserted', 'The table runs out of free buckets'], a: 0, e: 'A collision is two different keys mapping to the same bucket index, and it is unavoidable: the space of possible keys is larger than the number of buckets, so a hash table has to handle collisions rather than prevent them. Equal values are irrelevant, since the table indexes by key, and a table with no free buckets is a capacity problem solved by resizing - collisions happen long before that.', intro: 'There are far more possible keys than buckets. Ask what that forces to happen.', tags: ['DSA', 'Hash Tables'] },
  { q: 'Which is a common technique for handling collisions?', opts: ['Storing colliding entries in a list at the same bucket', 'Rejecting the second key and returning an error', 'Lengthening the hash until every key is unique', 'Sorting the table so colliding keys become adjacent'], a: 0, e: 'Separate chaining keeps a list per bucket, so colliding entries sit together and a lookup scans just that short list; open addressing is the other standard family, probing for a different slot. Rejecting a key is not an option - a table must accept every key it is given - and neither lengthening the hash nor sorting helps, because collisions come from reducing the hash to a bucket index and a hash table maintains no order.', intro: 'Ask what a table does when the bucket it computed is already occupied.', tags: ['DSA', 'Hash Tables'] },
  { q: 'In the worst case (many collisions), a hash table lookup can degrade to:', opts: ['O(1)', 'O(log n)', 'O(n)', 'O(n²)'], a: 2, e: 'If the hash sends every key to the same bucket the lookup walks that whole chain: with 400 colliding keys, finding the last one took 400 probes, against 3 when the same 400 keys were spread across 512 buckets. That is O(n), no better than scanning an array, and it is why a hash function an attacker can predict turns into a denial-of-service vector. O(log n) would require an ordered structure, which a hash table does not maintain.', intro: 'Picture every key landing in one bucket. What is left to search?', tags: ['DSA', 'Hash Tables'] },
  { q: 'In JavaScript, a Map or plain object is most often used to provide:', opts: ['Ordered range queries between two keys', 'Key-value lookups in average O(1)', 'Automatic balancing of a search tree', 'A fixed memory footprint regardless of size'], a: 1, e: 'Both give average O(1) access by key, which is the reason to reach for either. They are not interchangeable: a plain object coerces keys to strings, so o[1] and o["1"] are one entry, and it iterates integer-like keys in ascending numeric order before the rest, while a Map accepts any value as a key (a Map holding 1 and "1" has size 2) and iterates in insertion order. Neither answers range queries, neither maintains a tree, and both grow with the number of entries.', intro: 'Think about why you would reach for a Map instead of an array of key-value pairs.', tags: ['DSA', 'Hash Tables'] },
  { q: 'What property must a value have to work as a hash table key?', opts: ['It must be kept in sorted order', 'It must map to a consistent hash value', 'It must be an integer', 'It must be unique across all programs'], a: 1, e: 'Insertion hashes the key to choose a bucket and every lookup hashes it again; if the two hashes differ, the lookup searches the wrong bucket and the entry is invisible - which is exactly what happens when an object is mutated after being used as a key in a table hashed by its contents. Keys need not be integers (a JavaScript Map takes any value, and even NaN works, because Map compares with SameValueZero), need no global uniqueness, and are never kept sorted.', intro: 'Follow one key through an insert and then a lookup, and ask what would make the lookup miss.', tags: ['DSA', 'Hash Tables'] },
  { q: 'A hash table (hash set) is an excellent choice when you need to:', opts: ['Keep elements sorted', 'Test membership quickly', 'Always use minimal memory', 'Access elements by numeric index'], a: 1, e: 'A hash set hashes the value and checks one bucket, so membership does not get slower as the collection grows: scanning a 1000-element array for an absent value took 1000 comparisons, while Set.prototype.has checks a single bucket. What you give up is exactly what the other options ask for - a set has no order, so it cannot be kept sorted or indexed by position, and the bucket array plus per-entry overhead means it is not the minimal-memory choice.', intro: 'For each option, ask whether hashing the value alone could answer it.', tags: ['DSA', 'Hash Tables'] },

  // ── Level 6 — Stacks ───────────────────────────────────────────────────
  { q: 'A stack follows which ordering principle?', opts: ['FIFO (first in, first out)', 'Sorted order', 'LIFO (last in, first out)', 'Random order'], a: 2, e: 'A stack exposes only its top, so the most recently pushed element is the first one popped - that is what LIFO names. FIFO describes a queue, where the oldest element leaves first, and a stack imposes no ordering on the values themselves: pushing 3, 1, 2 pops 2, 1, 3, not 1, 2, 3.', intro: 'Picture a stack of plates: which one can you take without moving the others?', tags: ['DSA', 'Stacks'] },
  { q: 'An editor stores each new action on top of an undo history and removes the newest action first. Which operation pair matches that stack?', opts: ['enqueue and dequeue', 'push and pop', 'insert and remove-min', 'append and remove-first'], a: 1, e: 'push puts the newest action on top and pop removes that same most-recent action, which is the last-in-first-out behavior undo needs. enqueue and dequeue would undo the oldest action first, insert and remove-min would undo whichever action ranked lowest by some key, and append with remove-first is a queue under another name.', intro: 'The newest item is the one that leaves first. Which pair of operation names belongs to that end?', tags: ['DSA', 'Stacks'] },
  { q: 'What is the amortized time complexity of push and pop on a stack?', opts: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], a: 0, e: 'Push and pop act on the top only, so their cost does not depend on how deep the stack is - pushing onto an array touched one index whether it held 10, 20 or 40 elements, and popping touched one. For an array-backed stack this is amortized O(1): an occasional resize copies all n elements, but doubling the capacity spreads that cost over the pushes that follow. A linked-node stack is O(1) in the worst case as well, because it never resizes.', intro: 'Only one end is touched. Ask whether anything else in the structure has to move.', tags: ['DSA', 'Stacks'] },
  { q: 'What does the last line evaluate to?\n\n```js\nconst stack = [];\nstack.push(1);\nstack.push(2);\nstack.push(3);\nstack.pop();\n```', opts: ['1', '2', '3', 'undefined'], a: 2, e: 'A JavaScript array used as a stack pushes and pops at the end, so pop returns the most recently pushed value, 3, and leaves [1, 2]. Returning 1 would be queue behavior - first in, first out - and undefined comes back only when the stack is empty.', intro: 'Only the top is reachable. Which value is sitting there when pop runs?', tags: ['DSA', 'Stacks'] },
  { q: 'Which problem is naturally solved using a stack?', opts: ['Scheduling print jobs in order', 'Finding the shortest path', 'Sorting numbers', 'Matching balanced parentheses'], a: 3, e: 'Each opening bracket is pushed and each closing bracket must match the top of the stack, so "(a[b]{c})" is accepted while "([)]" and "((" are rejected - the first because the top is not the matching opener, the second because the stack is not empty at the end. Print scheduling is FIFO, shortest paths need a queue or a priority queue, and sorting needs comparisons rather than nesting.', intro: 'For each option, ask which item you need next: the newest, the oldest, or the smallest.', tags: ['DSA', 'Stacks'] },
  { q: '`a()` calls `b()`, and `b()` calls `c()`. In what order do the three frames leave the call stack?', opts: ['c, then b, then a', 'a, then b, then c', 'b, then c, then a', 'All three at once, when a() returns'], a: 0, e: 'A frame is pushed on entry and popped on return, so the innermost call finishes first: instrumenting a() calling b() calling c() logs a enter, b enter, c enter, c exit, b exit, a exit. That discipline is why the top frame is the first line of a stack trace and why unbounded recursion fills the stack. Releasing a() first would mean a caller finishing before the function it called, which cannot happen for synchronous calls.', intro: 'Trace where each frame sits while c() is running, then ask which one is on top.', tags: ['DSA', 'Stacks'] },
  { q: 'A parser needs to inspect the most recent opening bracket but keep it on the stack. Which operation should it use?', opts: ['pop', 'peek', 'dequeue', 'shift'], a: 1, e: 'peek, sometimes called top, returns the most recent item and leaves the stack unchanged, which is what a parser needs when the bracket may still match something later. pop would remove it, and dequeue and shift both take from the front, which on a stack is the oldest item rather than the newest.', intro: 'Compare the four on two points: which end they act on, and whether they remove anything.', tags: ['DSA', 'Stacks'] },
  { q: 'Which everyday feature is commonly implemented with a stack?', opts: ['Undo functionality in an editor', 'Autocomplete suggestions', 'Spell checking', 'Load balancing'], a: 0, e: 'Undo uses a stack: the last action performed is the first one undone (LIFO).', tags: ['DSA', 'Stacks'] },

  // ── Level 7 — Queues ───────────────────────────────────────────────────
  { q: 'A queue follows which ordering principle?', opts: ['LIFO (last in, first out)', 'Sorted order', 'FIFO (first in, first out)', 'Random order'], a: 2, e: 'A queue removes at the opposite end from where it adds, so the element that has waited longest leaves first - that is FIFO. LIFO is a stack, where the newest element leaves first, and a queue imposes no ordering on the values: enqueuing 3, 1, 2 dequeues 3, 1, 2 regardless of size.', intro: 'Picture a line at a counter: who gets served first?', tags: ['DSA', 'Queues'] },
  { q: 'Jobs must be added at the back and processed from the front in arrival order. Which operation pair matches that queue?', opts: ['push and pop at the same end', 'enqueue at the back and dequeue at the front', 'peek and remove-min', 'insert in sorted order and find'], a: 1, e: 'enqueue adds at the back and dequeue removes from the front, so jobs run in arrival order. Push and pop at the same end is a stack, which would run the newest job first; peek with remove-min is a priority queue, which orders by rank rather than arrival; and inserting in sorted order abandons arrival order altogether.', intro: 'Arrival order is the constraint. Check which pairs would reorder the jobs by something else.', tags: ['DSA', 'Queues'] },
  { q: 'For a queue backed by a circular buffer or a linked list, enqueue and dequeue are each:', opts: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], a: 0, e: 'A queue that tracks head and tail indexes in a circular buffer, or head and tail pointers in a linked list, touches a constant number of slots per operation, so both ends are O(1). A JavaScript array used as a queue is not that implementation: shift() moves every remaining element one place left - 40 index reads and 39 writes on a 40-element array - so draining n items costs O(n²) in total, against O(n) for a circular buffer.', intro: 'Ask what has to be true at the front so that removing there does not disturb the rest.', tags: ['DSA', 'Queues'] },
  { q: 'A queue starts empty. What does the final call return?\n\n```text\nenqueue("a")\nenqueue("b")\nenqueue("c")\ndequeue()\n```', opts: ['"a"', '"b"', '"c"', 'undefined'], a: 0, e: 'A queue is FIFO, so dequeue removes from the front - the earliest value enqueued, "a" - and leaves "b" and "c" waiting in that order. Returning "c" would be a stack\'s pop, and undefined comes back only from an empty queue, which this one is not.', intro: 'The two ends behave differently. Decide which end dequeue acts on before picking a value.', tags: ['DSA', 'Queues'] },
  { q: 'Which graph traversal uses a queue to visit nodes level by level?', opts: ['Breadth-first search', 'Depth-first search', 'In-order traversal of a binary tree', 'Backtracking search with pruning'], a: 0, e: 'BFS holds its frontier in a FIFO queue: dequeue a node, enqueue its unvisited neighbors, so everything at distance k is processed before anything at distance k+1 - on A to {B,C}, B to {D,E}, C to {F} the visit order is A, B, C, D, E, F. Swap the queue for a stack and the same code becomes depth-first, visiting A, C, F, B, E, D - one branch to the end before the other; in-order traversal and backtracking are likewise stack- or recursion-driven, so they dive deep before going wide.', intro: 'Ask what each traversal does with a node\'s neighbors: all of them next, or one of them next?', tags: ['DSA', 'Queues'] },
  { q: 'A sliding window needs to add items at one end and drop them from either end as it advances. Which structure supports that in O(1) per operation?', opts: ['A double-ended queue', 'A singly linked list with only a head pointer', 'A binary search tree', 'A hash set'], a: 0, e: 'A deque keeps handles on both head and tail, so adding or removing at either end is O(1) - what a sliding-window maximum or a capacity-limited undo/redo pair needs. A singly linked list with only a head can drop the front cheaply but needs O(n) to reach the tail, a search tree costs O(log n) per operation, and a hash set has no ends at all.', intro: 'For each option, work out what it costs to reach and remove at the far end.', tags: ['DSA', 'Queues'] },
  { q: 'Which scenario maps naturally to a queue?', opts: ['Evaluating nested parentheses', 'Processing tasks in arrival order', 'Reversing a string', 'Implementing recursion', ], a: 1, e: 'Tasks that must run in the order they arrived are FIFO, which a queue models directly: enqueue on arrival, dequeue to run. The other three are all LIFO - nested parentheses need the most recent unmatched opening bracket, reversing a string consumes characters newest-first, and recursion is the call stack itself - so recognizing \'most recent\' against \'longest waiting\' decides every one of them.', intro: 'For each scenario, ask whether the item you need next is the most recent one.', tags: ['DSA', 'Queues'] },
  { q: 'In a circular queue, the main advantage over a naive array queue is:', opts: ['It reuses freed front slots instead of shifting elements', 'It grows automatically when the buffer is full', 'It keeps the elements in sorted order', 'It removes the need to track the back of the queue'], a: 0, e: 'Head and tail indexes advance modulo the capacity, so a slot freed at the front is reused once the tail wraps around and no element ever moves. Counting element moves for n enqueues followed by n dequeues gives 500,500 for a shifting array queue at n = 1000, against 2,000 for a circular buffer. Wrapping does not create capacity - a full circular queue still has to resize or reject - and it needs both indexes, not fewer.', intro: 'Draw the buffer after a few enqueues and dequeues, and see which slots are now unused.', tags: ['DSA', 'Queues'] },

  // ── Level 8 — Linked Lists ─────────────────────────────────────────────
  { q: 'What is the time complexity of accessing the k-th element of a singly linked list by position?', opts: ['O(1)', 'O(log n)', 'O(n)', 'O(n²)'], a: 2, e: 'Nodes sit wherever they were allocated, so position k is reached only by following k next-pointers from the head: on a 100-node list, index 50 cost 50 hops and index 99 cost 99. That is O(n) in the worst case, against O(1) for an array\'s address computation. What the list buys in exchange is O(1) insertion after a node you already hold, with no shifting - removing that node is not free in a singly linked list, since its predecessor has to be found by walking from the head.', intro: 'There is no address arithmetic available here. Ask how you actually get from the head to position k.', tags: ['DSA', 'Linked Lists'] },
  { q: 'Each node in a singly linked list typically stores:', opts: ['Only a value', 'A value and an index', 'A value and a reference to the next node', 'Two values'], a: 2, e: 'A singly linked node holds its value plus a reference to the next node, with the last node\'s reference null - that chain is the whole structure. Storing an index instead would require the contiguous array a linked list exists to avoid, and every insertion would have to renumber all the nodes that follow, turning an O(1) splice into O(n).', intro: 'Picture the nodes scattered in memory in no particular order, and ask what still connects them.', tags: ['DSA', 'Linked Lists'] },
  { q: 'Inserting a node at the head of a linked list (given the head) is:', opts: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], a: 0, e: 'Inserting at the head allocates a node, points its next at the old head, and moves the head reference: two pointer writes on a 10-node list and the same two on a 100,000-node list, so the cost does not depend on n. Nothing else moves, which is the mirror image of an array, where inserting at the front shifts every existing element and costs O(n).', intro: 'Count the references that have to change, and ask whether the rest of the list notices.', tags: ['DSA', 'Linked Lists'] },
  { q: 'A doubly linked list differs from a singly linked list because each node also stores:', opts: ['A reference to the previous node', 'A reference to the head of the list', 'Its position index in the list', 'A copy of the previous node\'s value'], a: 0, e: 'Each node keeps prev as well as next, so traversal runs in both directions and a node you already hold can be removed in O(1) - a singly linked list has to walk from the head to find the predecessor first. The cost is one extra pointer per node and two links to keep consistent on every insertion and removal, which is where doubly linked list bugs come from.', intro: 'Ask which operations a singly linked list cannot do without walking from the head again.', tags: ['DSA', 'Linked Lists'] },
  { q: 'Given a reference to the node you want to change, what does a linked list do better than an array?', opts: ['Random access by index in O(1)', 'Lower memory per element', 'Insertion and deletion without shifting elements', 'Cache-friendly sequential scanning'], a: 2, e: 'Relinking pointers inserts or removes a node in constant time, while an array must move every element after the position: a front insert into a 100,000-element array costs 100,000 moves, the list costs one pointer write. Random access stays the array\'s advantage, because reaching index 50,000 in the list took 50,000 hops, and each node also carries a pointer, so a list uses more memory per element, not less.', intro: 'One structure computes an address from an index; the other only relinks pointers. Ask what each has to touch to remove a middle element.', tags: ['DSA', 'Linked Lists'] },
  { q: 'What special value typically marks the end of a singly linked list?', opts: ['The head', 'A null (or None) next pointer', 'A zero value', 'A loop back to the head'], a: 1, e: 'The last node\'s next is null, so a traversal written as while (node !== null) stops there; walking a two-node list visits 2 nodes and reads last.next as null. A zero value is data stored in a node, not a link, and a next pointer aimed back at the head describes a circular list, which makes that same loop run forever.', intro: 'Think about what the while loop tests before it steps to the next node.', tags: ['DSA', 'Linked Lists'] },
  { q: 'Which technique detects a cycle in a linked list using only constant extra space?', opts: ['Two pointers moving at different speeds', 'Binary search over the node values', 'A set of already-visited nodes', 'Sorting the nodes by value'], a: 0, e: 'Floyd\'s fast and slow pointers meet inside a cycle and use two variables, so the extra space is O(1). A visited-node set detects the same cycle but stores up to n node references, which the constant-space requirement rules out; binary search and sorting both need an ordering that a list of links does not provide.', intro: 'The list could hold a million nodes. Work out how much extra memory each approach needs at that size.', tags: ['DSA', 'Linked Lists'] },
  { q: 'In a singly linked list you hold a pointer to a node that is not the last one, and no pointer to its predecessor. How do you delete it?', opts: ['Reverse the list and delete from the front', 'Copy the next node\'s value in and skip the next node', 'Sort the list and drop the duplicate', 'Set the head to null and rebuild the list'], a: 1, e: 'Copying the successor\'s value into this node and unlinking the successor removes one value in O(1): applied to the node holding 2, the list [1,2,3,4] becomes [1,3,4]. It cannot be used on the last node, whose next is null, and it silently invalidates any outside pointer that still refers to the successor node.', intro: 'You cannot reach the predecessor\'s link, so change what this node holds instead.', tags: ['DSA', 'Linked Lists'] },

  // ── Level 9 — Recursion ────────────────────────────────────────────────
  { q: 'A function calls itself with the same argument every time and never returns. Which change lets it terminate correctly?', opts: ['Remove every return statement', 'Call the function again with the same input', 'Add a base case and recurse on a smaller input', 'Replace the parameter with a global variable'], a: 2, e: 'Termination needs a base case and arguments that approach it. A base case alone is not enough: in Node 22, a function that returns 0 at n === 0 but always recurses with the same n still throws RangeError: Maximum call stack size exceeded, exactly like a function with no base case at all.', intro: 'Look at what the argument is on call 1 and on call 1000, then ask what would have to differ.', tags: ['DSA', 'Recursion'] },
  { q: 'Every correct recursion must have a:', opts: ['Global variable', 'Loop inside it', 'Return type of void', 'Base case that stops the recursion'], a: 3, e: 'A base case terminates the recursion; without one it would recurse forever.', tags: ['DSA', 'Recursion'] },
  { q: 'What happens if a recursion has no reachable base case?', opts: ['It returns 0', 'It recurses until a stack overflow', 'It runs in O(1)', 'It is automatically optimized away'], a: 1, e: 'Each pending call keeps a frame on the call stack, so with no reachable base case the frames never pop: Node 22 throws RangeError: Maximum call stack size exceeded after roughly 12,500 frames in a simple function. Nothing optimizes it away either, because V8 does not implement proper tail calls, and a tail-recursive function in strict mode overflows at the same depth.', intro: 'Every call that has not returned still occupies a frame. Ask what runs out first.', tags: ['DSA', 'Recursion'] },
  { q: 'What does this return?\n\n```js\nfunction f(n) {\n  if (n <= 1) return 1;\n  return n * f(n - 1);\n}\nf(4);\n```', opts: ['10', '16', '24', '4'], a: 2, e: 'f(4) returns 4 * f(3), which unrolls to 4 * 3 * 2 * f(1); f(1) hits the base case and returns 1, so the product is 24 (running it in Node 22 returns 24). 10 is what you get by adding 4 + 3 + 2 + 1 instead of multiplying, and 16 is 4 squared, which this recursion never computes.', intro: 'Unroll the calls until n reaches 1, then multiply the returned values back up.', tags: ['DSA', 'Recursion'] },
  { q: 'Recursion uses which structure to keep track of pending calls?', opts: ['A queue', 'A hash table', 'A heap', 'The call stack'], a: 3, e: 'Each call pushes a frame holding its arguments and its return address, and frames pop in reverse order of calling, which is exactly stack behavior. That stack is finite: Node 22 reached about 12,500 frames before throwing RangeError: Maximum call stack size exceeded. A queue would return the oldest call first, which would resume the wrong frame.', intro: 'The most recent call is the first one to finish. Which structure has that order?', tags: ['DSA', 'Recursion'] },
  { q: 'A naive recursive Fibonacci (recomputing subproblems) has time complexity of about:', opts: ['O(n)', 'O(log n)', 'O(2ⁿ)', 'O(n²)'], a: 2, e: 'Every call fans out into two more and the same subproblems are recomputed, so the call count multiplies by roughly 1.618 per step: measured in Node 22, fib(10) makes 177 calls, fib(20) 21,891, fib(25) 242,785 and fib(30) 2,692,537. That is exponential, bounded above by 2^n (the exact rate is the golden ratio to the n), which is why O(n) or O(n squared) cannot describe it.', intro: 'Each call spawns two more. Count how the number of calls changes when n grows by one.', tags: ['DSA', 'Recursion'] },
  { q: 'Memoization speeds up recursion by:', opts: ['Storing each subproblem\'s result so it is computed once', 'Making every individual call cheaper to execute', 'Replacing the recursion with an equivalent loop', 'Shrinking the recursion depth to O(log n)'], a: 0, e: 'Memoization keeps a table of results, so each distinct input is computed once and later requests are lookups: in Node 22 naive fib(35) makes 29,860,703 calls while the memoized version makes 69. Individual calls are no cheaper, and the recursion is still recursion at depth n, so turning it into a loop is a different technique (tabulation), not what memoization does.', intro: 'The calls themselves do not get faster. Ask what stops happening.', tags: ['DSA', 'Recursion'] },
  { q: 'A tail-recursive call is one where the recursive call is:', opts: ['Placed before the base case check', 'The last operation performed before returning', 'Multiplied by the result of another call', 'Made once for each element of a loop'], a: 1, e: 'In tail position the recursive call is the last thing the function does, so its frame has no pending work and a compiler may reuse it. return n * f(n - 1) is not tail recursive, because the multiplication still waits on the result. ES2015 specifies proper tail calls, but V8 does not implement them: in Node 22 a strict-mode tail-recursive call at depth 1,000,000 still throws RangeError.', intro: 'Ask what still has to happen after the inner call returns its value.', tags: ['DSA', 'Recursion'] },

  // ── Level 10 — Sorting Algorithms ──────────────────────────────────────
  { q: 'What is the worst-case time complexity of bubble sort?', opts: ['O(n)', 'O(n log n)', 'O(n²)', 'O(log n)'], a: 2, e: 'Each pass compares adjacent pairs and the passes shrink by one, so a reversed input costs n(n-1)/2 comparisons: measured in Node 22, n = 8 took 28, n = 16 took 120 and n = 32 took 496, all exactly n(n-1)/2. O(n) is the best case only, and only for the early-exit variant, which finished an already-sorted 32-element array in 31 comparisons.', intro: 'Count the comparisons of the inner pass, then how many passes a fully reversed input forces.', tags: ['DSA', 'Sorting'] },
  { q: 'Merge sort\'s running time on any input, best, average or worst alike, is:', opts: ['O(n log n)', 'O(n)', 'O(n²)', 'O(log n)'], a: 0, e: 'Merge sort splits by position, not by value, so the recursion is always log2 n levels deep and each level merges n elements. Measured in Node 22 with n = 32, it used 80 comparisons on sorted input, 80 on reversed input and 122 on random input, all under n log2 n = 160. Quicksort also averages n log n but degrades to n squared on bad pivots; merge sort has no such input.', intro: 'Ask whether the split depends on the values in the array, or only on its length.', tags: ['DSA', 'Sorting'] },
  { q: 'What is the worst-case time complexity of quicksort?', opts: ['O(n log n)', 'O(n²)', 'O(log n)', 'O(n)'], a: 1, e: 'When the pivot is the smallest or largest remaining element, each partition removes only one element and the recursion is n levels deep, so the comparisons reach n(n-1)/2: with a last-element pivot on already-sorted input, Node 22 measured 28 comparisons at n = 8, 120 at n = 16 and 496 at n = 32. Random or median-of-three pivots restore the O(n log n) average, measured at 138 comparisons for n = 32, but the worst case never disappears.', intro: 'Picture the partition when every element lands on one side. How many partitions does that take?', tags: ['DSA', 'Sorting'] },
  { q: 'A sorting algorithm is "stable" when it:', opts: ['Sorts without allocating extra arrays', 'Compares each pair of elements at most once', 'Preserves the relative order of equal elements', 'Produces the same output on every run'], a: 2, e: 'A stable sort leaves equal-comparing elements in their input order, which is what lets you sort a table by name and then by department and keep the names ordered inside each department. Sorting without extra arrays is in-place, and producing the same output every run is determinism; an unstable sort can be both and still shuffle ties.', intro: 'Think about sorting a table by one column and then by another. One of these properties decides whether the first sort survives.', tags: ['DSA', 'Sorting'] },
  { q: 'Any sorting algorithm that orders elements only by comparing pairs needs, in the worst case, at least:', opts: ['Ω(n) comparisons', 'Ω(log n) comparisons', 'Ω(n log n) comparisons', 'Ω(1) comparisons'], a: 2, e: 'There are n! possible orderings and each comparison eliminates at most half of the remaining ones, so a decision tree needs at least log2(n!), which is Ω(n log n), comparisons in the worst case. A lower bound is written with Ω rather than O because O states an upper limit. The bound applies only to comparison sorts: counting sort and radix sort read the keys instead of comparing them and can run in O(n).', intro: 'Count how many orderings n elements can have, and how much one yes-or-no comparison can rule out.', tags: ['DSA', 'Sorting'] },
  { q: 'A typical in-place quicksort, compared with merge sort, is:', opts: ['Stable, exactly like merge sort', 'Not stable, because partitioning swaps distant elements', 'Stable whenever the input is already sorted', 'Stable whenever the pivot is the median'], a: 1, e: 'Partitioning exchanges elements across the array, so two equal values can end up in the opposite order from the input; that is why standard in-place quicksort is not stable. Merge sort is stable because the merge step takes from the left run whenever the two fronts compare equal. Neither a sorted input nor a perfect median pivot restores stability, they only change quicksort\'s running time.', intro: 'Watch where partitioning sends an element: to the neighboring slot, or anywhere across the array?', tags: ['DSA', 'Sorting'] },
  { q: 'Which sort can run in O(n) time on input that is already sorted?', opts: ['Merge sort', 'Selection sort', 'Heap sort', 'Insertion sort'], a: 3, e: 'On sorted input insertion sort\'s inner loop stops at the first comparison, so it does n-1 comparisons and no shifts: measured at n = 32, 31 comparisons and 0 shifts, against 496 comparisons on reversed input. The others cannot adapt: merge sort still splits and merges every level (80 comparisons on the same sorted input), selection sort always scans the rest of the array for a minimum (496), and heap sort still builds and drains a heap.', intro: 'For each element, ask how many comparisons the inner loop makes when the element before it is already smaller.', tags: ['DSA', 'Sorting'] },
  { q: 'Quicksort partitions the array around a chosen element called the:', opts: ['median node', 'root', 'pivot', 'sentinel'], a: 2, e: 'Quicksort picks a pivot, moves smaller elements before it and larger ones after it, then sorts the two sides. The choice matters as well as the name: with a last-element pivot on already-sorted input the partitions are maximally lopsided and comparisons hit n(n-1)/2, measured as 496 at n = 32, while a random pivot averaged 138. A root is the top of a tree and a sentinel is a placeholder node, neither of which quicksort uses.', intro: 'The name comes from what the element does: everything else is placed relative to it.', tags: ['DSA', 'Sorting'] },

  // ── Level 11 — Searching Algorithms ────────────────────────────────────
  { q: 'What is the worst-case time complexity of binary search on a sorted array?', opts: ['O(1)', 'O(n)', 'O(n log n)', 'O(log n)'], a: 3, e: 'Every comparison halves the remaining range, so the number of steps is how often n can be halved: measured in Node 22, the range shrinks to nothing in 10 steps for n = 1,000, 20 steps for n = 1,000,000 and 30 for n = 1,000,000,000. Multiplying n by 1,000 adds ten comparisons, which is what log n means; O(n log n) would be the cost of sorting the array, not of searching it.', intro: 'Ask how many times you can halve a range of n before only one element is left.', tags: ['DSA', 'Searching'] },
  { q: 'What must be true of the data for binary search to work?', opts: ['It must be sorted', 'It must be unique', 'It must be in a hash table', 'It must be a power of two in length'], a: 0, e: 'Discarding half the range is only justified if everything in that half is on the wrong side of the comparison, which is exactly what sortedness guarantees. On unsorted input the search fails silently: run on [9,1,7,3,5,2,8], it reports -1 for 7, 5 and 9 even though all three are present. Duplicates are fine, [1,2,2,2,5] finds 2, and the length need not be a power of two.', intro: 'Ask what the algorithm concludes about the half it throws away, and what makes that conclusion true.', tags: ['DSA', 'Searching'] },
  { q: 'Linear search on an unsorted list is, in the worst case:', opts: ['O(1)', 'O(log n)', 'O(n)', 'O(n²)'], a: 2, e: 'A scan stops only when it finds the target or runs out of elements, so the worst case is a missing value or one in the last position: n comparisons, measured as 100,000 for a 100,000-element array. Finding it in the first slot is the best case at a single comparison, while a random position averages about n/2, which is still O(n) because a constant factor does not change the growth. O(log n) would require sorted input, which the stem rules out.', intro: 'Think about where the value has to be for the scan to do the most work.', tags: ['DSA', 'Searching'] },
  { q: 'In binary search, after comparing with the middle element you:', opts: ['Restart from the beginning', 'Discard one element', 'Discard half of the remaining range', 'Sort the array again'], a: 2, e: 'If the middle element is smaller than the target, every element before it is smaller too, so that whole half is eliminated in one comparison; the same holds in the other direction. Halving repeatedly is what makes the cost log n: 20 comparisons cover a million elements. Discarding a single element per comparison would be linear search, which is the O(n) option.', intro: 'After one comparison with the middle element, ask which elements you now know cannot be the target.', tags: ['DSA', 'Searching'] },
  { q: 'For about 1,000,000 sorted elements, binary search needs roughly how many comparisons in the worst case?', opts: ['About 20', 'About 1,000', 'About 500,000', 'About 1,000,000'], a: 0, e: 'Halving a million takes about 20 steps because 2 to the 20th is 1,048,576, and running the search over a sorted array of 1,000,000 in Node 22 never exceeded 20 comparisons. The useful form of this is that every doubling of n costs one extra comparison, so a billion elements need only about 30. The 500,000 answer is what halving the work once, rather than halving repeatedly, would give.', intro: 'Start at a million and keep halving. Count how many halvings reach one.', tags: ['DSA', 'Searching'] },
  { q: 'What does this return when searching a sorted array for a value not present?\n\n```js\nfunction binarySearch(a, t) {\n  let lo = 0, hi = a.length - 1;\n  while (lo <= hi) {\n    const mid = (lo + hi) >> 1;\n    if (a[mid] === t) return mid;\n    if (a[mid] < t) lo = mid + 1;\n    else hi = mid - 1;\n  }\n  return -1;\n}\n```', opts: ['0', 'undefined', '-1', 'The array length'], a: 2, e: 'Each iteration pushes lo above mid or hi below mid, so a missing target ends with lo > hi, the while condition fails and control reaches return -1: searching [1,3,5,7,9,11,13] for 8 returns -1, while 7 returns index 3. undefined would need the function to fall off the end with no return at all, and 0 cannot be the sentinel because 0 is a legitimate index, which is why -1 is the conventional not-found value.', intro: 'Work out the values of lo and hi at the moment the loop condition finally fails.', tags: ['DSA', 'Searching'] },
  { q: 'Compared with linear search, binary search trades extra requirements for:', opts: ['Higher memory use', 'Working on unsorted data', 'A constant number of comparisons regardless of size', 'Far fewer comparisons on large sorted inputs'], a: 3, e: 'Binary search examines about log2 n elements instead of up to n: for 100,000 elements a scan made 100,000 comparisons while the binary search made 14. It is not constant time, since the count still grows with n, and it uses no extra memory, so the price is the sorted input rather than space.', intro: 'Both searches answer the same question. Compare only how many elements each one has to look at.', tags: ['DSA', 'Searching'] },
  { q: 'If you must search an unsorted array exactly once, sorting it first just to binary search is usually:', opts: ['Faster, because binary search is O(log n)', 'Not worth it, because sorting costs more than one scan', 'Required, because searching needs ordered input', 'Free, because sorting an array is O(n)'], a: 1, e: 'One scan costs at most n comparisons, while sorting first costs on the order of n log2 n before the search begins: at n = 100,000 that is 100,000 comparisons against roughly 1,660,000, and the binary search that follows takes only 14. Sorting pays for itself when the same array is searched many times, not once. Searching does not require sorted input in general, only binary search does.', intro: 'Add the cost of the sort to the cost of the search, then compare that total against one scan.', tags: ['DSA', 'Searching'] },

  // ── Level 12 — Trees ───────────────────────────────────────────────────
  { q: 'A traversal receives one entry node that has no parent and can reach every other node in the tree. Which role does it have?', opts: ['root', 'leaf', 'child', 'sibling'], a: 0, e: 'Only the root has no parent, and since every other node descends from it, a traversal starting there reaches the whole tree. A leaf is the opposite end, defined by having no children; a child is any node that does have a parent, and siblings are two nodes that share one.', intro: 'Two facts are given: no parent, and everything reachable. Which role needs both to be true?', tags: ['DSA', 'Trees'] },
  { q: 'During a depth-first traversal, which node can return immediately because there are no child subtrees to visit?', opts: ['root', 'parent', 'leaf', 'sibling'], a: 2, e: 'A leaf has no children, so the recursive call reaches it, finds nothing to descend into and returns at once: the leaf is the base case of every tree recursion, which is what keeps the traversal finite. A root normally does have children, and parent and sibling describe a node\'s relationships rather than whether it has any children of its own.', intro: 'The traversal stops descending where there is nothing below. Which node is that?', tags: ['DSA', 'Trees'] },
  { q: 'In a binary tree, how many children may a single node have?', opts: ['Exactly two, always', 'At most two', 'At least two', 'Any number'], a: 1, e: 'Binary caps the branching at two, conventionally named left and right, so a node may have two, one or none; a node with none is a leaf. \'Exactly two\' points at a full binary tree, where every internal node has two children while the leaves still have none, and \'any number\' describes a general tree such as a DOM node list.', intro: 'Picture a node with one child, and a node with none. Decide whether either of them breaks the definition.', tags: ['DSA', 'Trees'] },
  { q: 'The number of edges on the longest path from the root to a leaf is the tree’s:', opts: ['height', 'width', 'degree', 'order'], a: 0, e: 'Height is the number of edges on the longest root-to-leaf path, so a perfectly balanced tree of 1,023 nodes has height 9 and one of 1,048,575 nodes has height 19. Some texts count nodes instead, which gives an answer one larger, so it is worth stating which convention is in use. Degree is the number of children a node has and order is the maximum branching factor; neither measures depth.', intro: 'The stem already describes the measurement. Recall which word names it, and note that it counts edges rather than nodes.', tags: ['DSA', 'Trees'] },
  { q: 'Which traversal visits left subtree, then node, then right subtree?', opts: ['Pre-order', 'Post-order', 'In-order', 'Level-order'], a: 2, e: 'In-order places the node between its two subtrees, which is what makes it produce sorted output on a binary search tree. On the tree with root 50, children 30 and 70 and leaves 20, 40, 60, 80, the four orders are: in-order [20,30,40,50,60,70,80], pre-order [50,30,20,40,70,60,80] with the node first, post-order [20,40,30,60,80,70,50] with the node last, and level-order [50,30,70,20,40,60,80] row by row.', intro: 'The prefix says where the node itself is visited relative to its subtrees.', tags: ['DSA', 'Trees'] },
  { q: 'A depth-first traversal of a tree is naturally implemented with:', opts: ['A queue of nodes waiting to be visited', 'A hash table of already-visited nodes', 'A stack, explicit or the call stack', 'A sorted array of node values'], a: 2, e: 'Depth-first finishes one child\'s subtree before starting the next, so postponed nodes must be resumed in reverse order of arrival, which is what a stack does, and recursion gets that stack for free. A queue resumes the oldest pending node first, which is a level-order walk: on a tree with root 50, children 30 and 70, and leaves 20, 40, 60 and 80, it yields [50,30,70,20,40,60,80] instead. A tree has no cycles, so no visited set is needed.', intro: 'The last node you postponed is the first one you come back to. Which structure has that order?', tags: ['DSA', 'Trees'] },
  { q: 'Level-order (breadth-first) tree traversal uses which structure?', opts: ['A stack', 'A queue', 'A heap', 'A linked list of leaves'], a: 1, e: 'Enqueueing a node\'s children and dequeueing from the front visits the tree row by row: on the tree rooted at 50 this gives [50,30,70,20,40,60,80]. A stack would return the newest node first, producing a depth-first order. One JavaScript caveat: the specified algorithm for Array.prototype.shift copies every remaining element down one index, so a large traversal should advance a head index instead of calling shift.', intro: 'Nodes have to come out in the order they were discovered, oldest first. Which structure guarantees that?', tags: ['DSA', 'Trees'] },
  { q: 'A binary tree of n nodes that is balanced has a height of about:', opts: ['O(n)', 'O(n²)', 'O(log n)', 'O(1)'], a: 2, e: 'Level k holds up to 2 to the k nodes, so n nodes fit in about log2 n levels: measured, a perfectly balanced tree of 1,023 nodes has height 9 and one of 1,048,575 nodes has height 19. O(n) is not a nonsense answer but the unbalanced case, where each node has one child and the tree degenerates into a list; keeping height at log n is exactly what balancing is for.', intro: 'Each level can hold twice as many nodes as the one above it. Ask how many levels n nodes need.', tags: ['DSA', 'Trees'] },

  // ── Level 13 — Binary Search Trees ─────────────────────────────────────
  { q: 'What is the defining ordering property of a binary search tree (BST)?', opts: ['All left-subtree values are smaller, all right-subtree values larger', 'Only the immediate left child is smaller and the right child larger', 'All left-subtree values are larger, all right-subtree values smaller', 'No ordering is imposed between a node and its descendants'], a: 0, e: 'The invariant covers entire subtrees: a node buried deep on the left must still be smaller than the root, which is what lets a search discard a whole subtree at each step. Checking only the immediate children is the classic mistake and accepts trees whose in-order traversal is not sorted. Implementations usually assume distinct keys and send duplicates consistently to one side.', intro: 'Ask whether the rule constrains the two children only, or everything beneath them.', tags: ['DSA', 'BST'] },
  { q: 'In a balanced BST, searching for a value takes:', opts: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], a: 2, e: 'A search visits one node per level, so its cost is the height, and balancing keeps the height near log2 n: in a balanced BST of 1,023 nodes the worst-case search touched 10 nodes. Drop the balance assumption and the same n nodes can form a single chain, where the worst-case search touched all 1,023, which is the O(n) option.', intro: 'A search follows one path from the root downward. What limits how long that path can be?', tags: ['DSA', 'BST'] },
  { q: 'What is the worst-case search time of an unbalanced BST (e.g. inserted in sorted order)?', opts: ['O(n)', 'O(1)', 'O(log n)', 'O(n log n)'], a: 0, e: 'Each sorted insert lands to the right of everything before it, so the tree becomes one long chain: built from 1..1023 in order, the chain is 1023 nodes deep and the worst-case search visits all 1023. O(log n) is the balanced case - the same 1023 values arranged as a balanced tree are 10 levels deep, with a worst case of 10 visits - and that is exactly what the word unbalanced takes away. A single search never costs O(n log n); that shape belongs to sorting.', intro: 'Draw the tree after inserting 1, 2, 3, 4 in that order. How many nodes must a search pass through?', tags: ['DSA', 'BST'] },
  { q: 'An in-order traversal of a BST visits the values in:', opts: ['Descending order', 'Insertion order', 'Sorted ascending order', 'Level order'], a: 2, e: 'In-order visits the left subtree, then the node, then the right subtree, and a BST keeps every smaller value on the left, so the values come out ascending: traversing a BST built from a shuffled 1..1023 returned exactly 1, 2, 3, ... 1023. Descending is the mirror walk, right-node-left. Insertion order is not recoverable from the tree at all, and level order is a breadth-first walk that ignores the ordering property.', intro: 'In-order means left subtree, then node, then right subtree. Recall which values a BST keeps in the left subtree.', tags: ['DSA', 'BST'] },
  { q: 'Where is the minimum value found in a non-empty BST?', opts: ['At the root', 'The rightmost node', 'The leftmost node', 'Any leaf'], a: 2, e: 'The BST rule puts every smaller value in the left subtree, so walking left until there is no left child reaches the smallest value: in a BST built from a shuffled 1..1023 that walk ended at 1. The rightmost node is the mirror image and holds the maximum, 1023 in the same tree. Any leaf fails twice over: most leaves are not the minimum, and the leftmost node need not even be a leaf, since it can still have a right child.', intro: 'Every value in a left subtree is smaller than its parent. Keep applying that rule and see where you have to stop.', tags: ['DSA', 'BST'] },
  { q: 'Self-balancing BSTs such as AVL or Red-Black trees exist primarily to:', opts: ['Bound the height so operations stay O(log n)', 'Reduce the memory each node needs', 'Store duplicate keys without extra work', 'Traverse the tree without using recursion'], a: 0, e: 'Rotations after each insert and delete keep the height near log2 n, and the height is what bounds the worst case: inserting 1..1023 in sorted order produced an AVL tree only 10 levels deep, while the same inserts left a plain BST as a 1023-node chain. Memory runs the other way, since every node has to carry an extra height or color field. Duplicate keys and recursion are unrelated to balancing - AVL insertion is usually written recursively.', intro: 'Ask what goes wrong in a plain BST when the keys happen to arrive in sorted order.', tags: ['DSA', 'BST'] },
  { q: 'To insert into a BST, you compare with the current node and:', opts: ['Insert at the root and push the old root down', 'Go left if larger, right if smaller, until a spot is free', 'Append at the first free spot on the bottom row', 'Go left if smaller, right if larger, until a spot is free'], a: 3, e: 'Insertion follows exactly the comparison a search follows - smaller to the left, larger to the right - and stops at the first empty child slot, which is what keeps the ordering property true: inserting 1023 shuffled values this way produced a tree whose in-order traversal was exactly 1..1023. Appending at the first free spot on the bottom row is the heap rule and would break the BST ordering. Reversing the comparison builds a tree sorted the other way, so every later search that trusts the ordering would miss.', intro: 'The rule that decides where a value is placed is the same rule that has to find it again later.', tags: ['DSA', 'BST'] },
  { q: 'Deleting a BST node that has two children must keep the ordering property intact. Which value should replace the deleted one?', opts: ['The value at the tree\'s root', 'Its in-order successor (or predecessor)', 'Its left child, dropping the right subtree', 'The value inserted most recently'], a: 1, e: 'The in-order successor is the smallest value in the right subtree, and the predecessor the largest in the left; either is the only value that still stands above everything on the left and below everything on the right, so the ordering survives. Deleting 200 nodes with the successor rule left the tree valid with all 823 remaining values intact. Splicing in the left child alone also leaves a valid BST, which is why it looks safe, but it silently discards the right subtree: the same 200 deletions left only 364 of the 823 values.', intro: 'Only one value can sit between the deleted node\'s two subtrees without breaking the order. Which one is it?', tags: ['DSA', 'BST'] },

  // ── Level 14 — Heaps & Priority Queues ─────────────────────────────────
  { q: 'In a min-heap holding many values, where does the smallest value sit?', opts: ['In a leaf, because small values sink', 'In the last slot of the backing array', 'At the root, above every other value', 'Wherever it was inserted, since heaps only reorder on demand'], a: 2, e: 'Every node in a min-heap is at least as large as its parent, so from any node you can walk upward through non-increasing values until you reach the root, which makes the root the minimum. A heap of 1048576 shuffled values held 1 at index 0, and through 1000 mixed pushes and pops index 0 kept holding the smallest value still in the heap. Leaves hold the large values, the backing array is not sorted so its last slot means nothing, and the sift-up on every insert is exactly the reordering that a heap is claimed not to do.', intro: 'The heap rule compares each node only with its parent. Follow that comparison upward from any node and see where you end up.', tags: ['DSA', 'Heaps'] },
  { q: 'What is the time complexity of finding (peeking at) the minimum in a min-heap?', opts: ['O(1)', 'O(log n)', 'O(n)', 'O(n log n)'], a: 0, e: 'The heap-order property pins the minimum at index 0, so peeking is a single array read whose cost does not grow with n: on heaps of 16 and of 1048576 elements the peek was one access either way. O(log n) is the cost of extract-min, which removes the root and then sifts a replacement down the full height - confusing peeking with extracting is the usual mistake. O(n) would mean scanning the array, which the invariant makes unnecessary.', intro: 'Peeking does not change the heap. Recall which position the heap-order property pins the minimum to.', tags: ['DSA', 'Heaps'] },
  { q: 'What is the worst-case time complexity of inserting one element into a binary heap of n elements?', opts: ['O(1)', 'O(n)', 'O(log n)', 'O(n²)'], a: 2, e: 'An insert appends at the end of the array and sifts the value up one parent at a time, so the number of swaps is bounded by the height, about log2 n: on a heap of 1048575 elements the deepest sift-up took 19 swaps, matching floor(log2 n). Average behavior is far cheaper - inserting the same values in random order needed about 1.3 swaps per insert - which is why O(1) is the average-case answer rather than a nonsense one, and why the stem has to say which case it means. O(n) would mean touching the whole array, which a sift-up never does.', intro: 'A new value enters at the bottom and can only move upward along one path. How long can that path be?', tags: ['DSA', 'Heaps'] },
  { q: 'Removing the minimum (extract-min) from a binary heap of n elements costs, in the worst case:', opts: ['O(1)', 'O(n)', 'O(n log n)', 'O(log n)'], a: 3, e: 'Extract-min removes the root, moves the last element into its place and sifts it down one level at a time, so the work is bounded by the height. Over 200000 extractions from a 1048575-element heap the deepest sift-down was 19 swaps, exactly floor(log2 n), and the average was 18.6 - unlike insertion, this operation is logarithmic on average as well as in the worst case. O(1) is what peeking at the minimum costs when you do not remove it, which is the usual confusion.', intro: 'The root is gone, so a value from the bottom takes its place and has to settle. Count the levels it can fall through.', tags: ['DSA', 'Heaps'] },
  { q: 'A binary heap is most commonly implemented using:', opts: ['A binary tree of linked nodes', 'An array indexed level by level', 'A hash map from index to value', 'A linked list in level order'], a: 1, e: 'Because a binary heap is complete, laying it out in level order leaves no holes, so with 0-based indices the children of position i are always at 2i+1 and 2i+2 and the parent at floor((i-1)/2); a 1048576-element heap built on exactly that arithmetic stayed valid throughout. A 1-based array uses 2i and 2i+1 instead, which is why the convention has to be stated. Linked nodes or a hash map would also work, but each step then costs a pointer chase or a hash lookup and gives up the contiguous layout that makes the index arithmetic free.', intro: 'A binary heap is always a complete tree, with no gaps on any level but the last. What does that let you compute instead of store?', tags: ['DSA', 'Heaps'] },
  { q: 'A priority queue must repeatedly insert values and remove the highest-priority one. Which structure keeps both operations efficient as n grows?', opts: ['A heap', 'A plain array', 'A hash table', 'A singly linked list'], a: 0, e: 'A heap keeps both insert and remove-min at O(log n) because each one walks a single root-to-leaf path: pushing and then draining 100000 values cost about 30 operations per element. An unsorted array makes insert trivial but pays for it on every removal, which has to scan for the minimum - the same workload cost about 50000 operations per element - and keeping a list sorted just moves that linear cost into the insert. A hash table has no ordering at all, so it cannot find the highest-priority entry without a full scan.', intro: 'Two operations have to stay cheap at the same time. Ask which structure avoids scanning everything on the removal.', tags: ['DSA', 'Heaps'] },
  { q: 'Building a heap from an unsorted array of n elements (heapify) can be done in:', opts: ['O(n)', 'O(log n)', 'O(n log n)', 'O(n squared)'], a: 0, e: 'Bottom-up heapify sifts each element down at most its own height, and almost all elements sit near the bottom: half are leaves that move zero levels, a quarter move at most one, and the total stays proportional to n. Measured, building heaps of 1023 and of 1048575 elements took about 0.7 swaps per element at both sizes - a constant, not a growing one. O(n log n) is what you get by inserting the n elements one at a time, which cost 18.0 swaps per element on the worst-case input at the same size.', intro: 'Half the elements are leaves and need no work at all. Ask how far the typical element actually has to sift.', tags: ['DSA', 'Heaps'] },
  { q: 'Heap sort works by building a heap and repeatedly extracting the root; its overall time complexity is:', opts: ['O(n)', 'O(n²)', 'O(log n)', 'O(n log n)'], a: 3, e: 'The build phase is linear, but each of the n extract-min operations sifts a replacement down about log2 n levels, so the removals dominate and the total is n log n. Counted comparisons stayed between 1.69 and 1.84 times n times log2 n as n grew from 1024 to 1048576 - a bounded constant, not a growing one. O(n) is the cost of the build phase alone, the tempting mistake immediately after learning that heapify is linear, and O(n squared) would require each removal to scan the whole array, which sifting down never does.', intro: 'Building the heap is the cheap half. Count what the n removals cost, since each one has to restore the heap.', tags: ['DSA', 'Heaps'] },

  // ── Level 15 — Graphs ──────────────────────────────────────────────────
  { q: 'A graph is composed of:', opts: ['Vertices that must all be connected', 'A single root and its descendants', 'Vertices and the edges connecting them', 'A square matrix of connection flags'], a: 2, e: 'A graph is a set of vertices together with a set of edges, each edge joining a pair of vertices; both parts are part of the definition. Connectivity is not required, so a graph may fall into several disconnected pieces, and a rooted tree is only the special case with no cycles and one designated root. A square matrix of flags is one way to store a graph - the adjacency matrix - not what a graph is.', intro: 'Ask what a graph could still express if you took away the connections and kept only the objects.', tags: ['DSA', 'Graphs'] },
  { q: 'In a directed graph, an edge:', opts: ['may be followed from either endpoint', 'always comes with a matching reverse edge', 'runs one way, from a source to a target', 'carries a weight in addition to a direction'], a: 2, e: 'A directed edge is an ordered pair: it runs from a source vertex to a target, and its existence says nothing about whether the reverse edge exists. That asymmetry is the point - you may not follow it backward unless the reverse edge is separately present, which is why reachability in a directed graph has to be computed rather than assumed. Weights are a separate, optional attribute; a directed edge does not need one.', intro: 'An undirected edge is an unordered pair of endpoints. Ask what changes once that pair becomes ordered.', tags: ['DSA', 'Graphs'] },
  { q: 'Using adjacency lists, what is the time complexity of breadth-first search over a graph with V vertices and E edges?', opts: ['O(V)', 'O(E)', 'O(V + E)', 'O(V × E)'], a: 2, e: 'Each vertex is enqueued and dequeued once and each adjacency-list entry is read once, so the total is proportional to V plus E: on a graph with V = 64000 and E = 69232 the traversal made exactly 64000 vertex visits and 138464 edge inspections, which is 2E because an undirected edge appears in both endpoints\' lists. O(V) ignores the edge scanning and O(E) ignores isolated vertices, so neither bound covers both halves of the work. The representation is what makes this bound true - the same BFS over an adjacency matrix inspected V squared, or 4096000000, cells on that graph.', intro: 'Half the graph could be vertices that no edge touches, while one vertex could have a thousand neighbors. A bound has to survive both.', tags: ['DSA', 'Graphs'] },
  { q: 'Using adjacency lists, what is the time complexity of depth-first search over a graph with V vertices and E edges?', opts: ['O(V + E)', 'O(V²)', 'O(E²)', 'O(log V)'], a: 0, e: 'DFS marks each vertex once and reads each adjacency-list entry once, so it does the same V plus E work that BFS does and only the visit order differs: on a graph with V = 64000 and E = 69232, both traversals made 64000 vertex visits and 138464 edge inspections. O(V squared) is not a random wrong answer - it is what DFS costs on an adjacency matrix, where finding a vertex\'s neighbors means scanning a whole row of V cells, which came to 4096000000 inspections on that same graph. That is why the stem has to say which representation it assumes.', intro: 'Ask whether the walk can read the same neighbor list a second time, and what stops it.', tags: ['DSA', 'Graphs'] },
  { q: 'Which data structure does BFS use to manage which vertex to visit next?', opts: ['A stack', 'A heap', 'A queue', 'A binary search tree'], a: 2, e: 'A queue is first-in-first-out, so vertices leave it in the order they were discovered and BFS finishes every vertex at distance k before any at distance k+1. Take a source with three neighbors, one of which starts a chain of three more: the queue-driven walk visits them at distances 0,1,1,1,2,3,4, while swapping in a stack sends the same code down the chain first, at distances 0,1,2,3,4,1,1 - a depth-first walk, so the shortest-path distances BFS is used for come out wrong. A heap would order by priority rather than by discovery, which gives Dijkstra, not BFS.', intro: 'BFS is usually run to get the number of steps from the source. Ask which container would let a far vertex come out before a near one.', tags: ['DSA', 'Graphs'] },
  { q: 'An adjacency matrix representation of a graph with V vertices uses how much space?', opts: ['O(V)', 'O(V + E)', 'O(V²)', 'O(E)'], a: 2, e: 'An adjacency matrix reserves one cell for every ordered pair of vertices, so the space is V times V no matter how many edges exist: at V = 64000 that is 4096000000 cells, while the same sparse graph\'s adjacency lists held 138464 entries. O(V + E) is the adjacency-list cost and O(E) counts only the edges that are present - the matrix pays for the absent ones too. It earns that space back only on dense graphs, where E approaches V squared, and by answering is there an edge from a to b in constant time.', intro: 'Work out the cost for a graph with no edges at all, then for one with every possible edge. Compare the two.', tags: ['DSA', 'Graphs'] },
  { q: 'Dijkstra’s algorithm is used to find:', opts: ['the cheapest set of edges connecting every vertex', 'shortest paths from one source, given non-negative weights', 'an ordering of vertices that respects every dependency', 'the groups of vertices that can all reach each other'], a: 1, e: 'Dijkstra grows a set of settled vertices outward from a single source, always finishing the nearest unsettled vertex, which yields the shortest distance from that source to every other vertex. The method holds only while no edge weight is negative: on a four-vertex graph with one weight of -3 it reported a distance of 5 where the true shortest path costs 3, because it had already settled that vertex and never reconsidered it. A minimum spanning tree is a different object - the cheapest edge set that connects everything, which need not contain any shortest path - while topological order and strongly connected components ignore weights entirely.', intro: 'Cheapest route from one chosen vertex and cheapest set of edges overall are different results. Two of these options are exactly that pair.', tags: ['DSA', 'Graphs'] },
  { q: 'A topological sort can be performed on which kind of graph?', opts: ['Any graph, directed or not', 'Any directed graph, cycles included', 'An undirected graph with no cycles', 'A directed graph with no cycles'], a: 3, e: 'A topological order lists the vertices so that every edge points forward, which needs direction - an undirected edge gives no meaning to before - and forbids cycles, since a cycle would require each of its vertices to come before itself. Running Kahn\'s algorithm on a five-vertex directed acyclic graph (a DAG) emitted all five in order; on a graph containing the cycle 0 to 1 to 2 to 0 it emitted none of the four, because no vertex ever reaches in-degree zero. Treating undirected edges as edges in both directions makes every edge a two-cycle, so that case fails for exactly the same reason.', intro: 'Try to write a valid order for three tasks where each one waits on the next, in a loop. Where you get stuck is half the answer.', tags: ['DSA', 'Graphs'] },
];
